#!/usr/bin/env python3
"""Build statique du portail impérial, sans dépendances externes."""
from pathlib import Path
from html import escape as esc
import json,sys,re
from content import ARTICLES
ROOT=Path(__file__).resolve().parents[1]
SITE=ROOT/'site'
ARTICLE={a['slug']:a for a in ARTICLES}

def link(root,target): return root+target

def breadcrumb(base, chain):
    res=['<div class="breadcrumbs"><a href="'+base+'">Accueil</a>']
    for label,url in chain:
        res.append('<span class="sep">/</span>')
        res.append((f'<a href="{base}{esc(url)}">{esc(label)}</a>' if url else '<span>'+esc(label)+'</span>'))
    return ''.join(res)+'</div>'

def nav(base,active):
    items=[('Accueil','', 'accueil'),('L’Empire','empire/','empire'),('Territoires','territoires/','territoires'),('Arélia Maps','maps/','atlas'),('Actualités','journal/','journal'),('Encyclopédie','wiki/','wiki')]
    return '<header class="navbar"><div class="container navbar-inner"><a href="'+base+'" class="identity" aria-label="Portail impérial d’Arélia, accueil"><span class="identity-mark" aria-hidden="true">✳</span><span><span class="identity-name">ARÉLIA</span><span class="identity-caption">Portail impérial</span></span></a><nav class="navlinks" aria-label="Navigation principale">'+''.join(f'<a href="{base}{href}"'+(' class="active" aria-current="page"' if active==key else '')+'>'+label+'</a>' for label,href,key in items)+'</nav><div class="nav-actions"><a href="'+base+'wiki/" class="btn btn-outline">Explorer le wiki <span aria-hidden="true">↗</span></a><button type="button" class="mobile-toggle" data-nav-toggle aria-label="Ouvrir le menu" aria-expanded="false">☰</button></div></div></header>'

def footer(base):
    return f'''<footer class="footer"><div class="container"><div class="footer-grid"><div><a href="{base}" class="identity"><span class="identity-mark" aria-hidden="true">✳</span><span><span class="identity-name">ARÉLIA</span><span class="identity-caption">Portail impérial</span></span></a><p>Un pays imaginaire à découvrir. Atlas, institutions et encyclopédie d’un univers fictif en construction.</p></div><div><h4>Le portail</h4><div class="footer-links"><a href="{base}empire/">Institutions</a><a href="{base}territoires/">Territoires et villes</a><a href="{base}atlas/">Atlas interactif</a><a href="{base}journal/">Journal de création</a></div></div><div><h4>Encyclopédie</h4><div class="footer-links"><a href="{base}wiki/">Tous les articles</a><a href="{base}wiki/arelia/">Présentation générale</a><a href="{base}wiki/chronologie/">Chronologie</a><a href="{base}wiki/empire-constitutionnel/">Empire constitutionnel</a></div></div></div><div class="footer-bottom"><span>© Arélia — Projet de fiction et de worldbuilding. Aucune institution réelle.</span><span>Conçu pour GitHub Pages · Données canoniques versionnées</span></div></div></footer>'''

def layout(path,title,description,content,active='accueil'):
    d=Path(path).parent.parts
    base='../'*len(d) or './'
    canonical=esc(title+' | Arélia')
    html=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><meta name="theme-color" content="#0c1e2b"><meta name="description" content="{esc(description,quote=True)}"><title>{canonical}</title><link rel="icon" href="{base}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{base}assets/site.css"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><meta property="og:type" content="website"><meta property="og:title" content="{canonical}"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:image" content="{base}assets/arelia-horizon.webp"></head><body><a href="#main" class="skip-link">Aller au contenu</a><div class="sitebar"><div class="container"><span>Empire constitutionnel d’Arélia · Portail de l’univers</span><span class="right">Monde fictif · Édition de référence</span></div></div>{nav(base,active)}<main id="main">{content}</main>{footer(base)}<script src="{base}assets/site.js" defer></script></body></html>'''
    out=SITE/path
    out.parent.mkdir(parents=True,exist_ok=True)
    out.write_text(html,encoding='utf-8')

def head(base,chain,eyebrow,title,description):
    return f'<section class="page-head"><div class="container">{breadcrumb(base,chain)}<div class="eyebrow">{esc(eyebrow)}</div><h1>{esc(title)}</h1><p>{esc(description)}</p></div></section>'

def art_row(base,slug):
    a=ARTICLE[slug];return f'<a class="article-row" href="{base}wiki/{slug}/"><span><strong>{esc(a["title"])}</strong><small>{esc(a["category"])} · {esc(a["status"])}</small></span><span class="arrow" aria-hidden="true">↗</span></a>'

# Accueil
base='./'
home=f'''<section class="hero"><img class="hero-img" src="assets/arelia-horizon.webp" alt="Vue panoramique d’une grande île aux montagnes et métropoles côtières" fetchpriority="high"><div class="container fadein"><span class="eyebrow">Portail de l’Empire constitutionnel</span><h1>Un territoire.<br><em>Mille horizons.</em></h1><p>Des sommets enneigés du Nord aux cités du littoral, explorez Arélia : un empire insulaire de cent millions d’habitants, au patrimoine naturel et urbain exceptionnel.</p><div class="hero-actions"><a href="maps/" class="btn btn-gold">Explorer la carte <span aria-hidden="true">↗</span></a><a href="empire/" class="btn btn-ghost">Découvrir l’Empire <span aria-hidden="true">→</span></a></div></div><div class="scroll-cue">Découvrir <span>↓</span></div></section>
<div class="stats-band"><div class="container stats-grid"><div class="stat"><span>Population</span><strong>100 millions</strong></div><div class="stat"><span>Superficie</span><strong>1 million de km²</strong></div><div class="stat"><span>Capitale impériale</span><strong>Vésone</strong></div><div class="stat"><span>Régime politique</span><strong>Empire constitutionnel</strong></div></div></div>
<section class="section"><div class="container intro-grid"><div><span class="eyebrow dark">Bienvenue en Arélia</span><h2 class="large-quote">Une île-continent entre nature, cités et histoire à inventer.</h2><p class="body-copy">Arélia se déploie sur un million de kilomètres carrés : des montagnes glaciaires, un réseau fluvial traversant les plaines, des métropoles ouvertes sur l’océan, un grand massif forestier et un désert volcanique. Le portail présente ce monde de l’intérieur ; l’encyclopédie rassemble les connaissances de l’univers.</p><a class="text-link" href="wiki/arelia/">Lire la présentation générale <span>↗</span></a></div><div class="feature-image"><img src="assets/arelia-geographie.webp" alt="Carte panoramique des régions et paysages d’Arélia" loading="lazy"><div class="feature-tag"><small>Le territoire</small><strong>Un million de km²</strong></div></div></div></section>
<section class="section section-cream"><div class="container"><div class="section-heading"><div><span class="eyebrow dark">Les grands ensembles</span><h2>Un pays, plusieurs mondes.</h2></div><p>Des régions aux contrastes saisissants dessinent la géographie d’Arélia et façonnent ses villes.</p></div><div class="grid-three"><a href="wiki/massif-nord/" class="editorial-card"><div class="pic alt-three"><img src="assets/arelia-geographie.webp" alt="Massif montagneux enneigé" loading="lazy"></div><div class="content"><span class="eyebrow dark">01 · Le Nord</span><h3>Hautes terres & glaciers</h3><p>Chaînes alpines, lacs d’altitude, glaciers et étendues polaires.</p><span class="text-link">Découvrir la région ↗</span></div></a><a href="wiki/foret-arelia/" class="editorial-card"><div class="pic alt-two"><img src="assets/arelia-geographie.webp" alt="Grand massif forestier" loading="lazy"></div><div class="content"><span class="eyebrow dark">02 · Le cœur vert</span><h3>Forêt & vallées</h3><p>Fleuves, grands paysages de forêt humide et plaines agricoles.</p><span class="text-link">Découvrir la région ↗</span></div></a><a href="wiki/desert-solmar/" class="editorial-card"><div class="pic alt-one"><img src="assets/arelia-geographie.webp" alt="Désert et zone volcanique d’Azran" loading="lazy"></div><div class="content"><span class="eyebrow dark">03 · Le Sud</span><h3>Désert & volcan</h3><p>Sables de Solmar, formations minérales et volcan d’Azran.</p><span class="text-link">Découvrir la région ↗</span></div></a></div></div></section>
<section class="section"><div class="container"><div class="section-heading"><div><span class="eyebrow dark">Les centres de vie</span><h2>Les villes d’Arélia</h2></div><a class="text-link" href="territoires/">Toutes les villes ↗</a></div><div class="feature-rows"><div class="feature-row"><span class="eyebrow dark">Capitale impériale</span><h3>Vésone</h3><p>Une cité de canaux, de ponts et d’institutions, au centre-est de l’île.</p><a href="wiki/vesone/" class="text-link">Explorer Vésone ↗</a></div><div class="feature-row"><span class="eyebrow dark">Métropole portuaire</span><h3>Occidian</h3><p>La porte maritime du grand fleuve central sur la côte occidentale.</p><a href="wiki/occidian/" class="text-link">Explorer Occidian ↗</a></div><div class="feature-row"><span class="eyebrow dark">Métropole méridionale</span><h3>Orientale</h3><p>La ville du Sud, à la rencontre du désert et des grandes routes maritimes.</p><a href="wiki/orientale/" class="text-link">Explorer Orientale ↗</a></div><div class="feature-row"><span class="eyebrow dark">Métropole septentrionale</span><h3>Katoru</h3><p>La grande cité des mers froides et des paysages de haute montagne.</p><a href="wiki/katoru/" class="text-link">Explorer Katoru ↗</a></div></div></div></section>
<section class="wide-banner"><div class="container"><div><span class="eyebrow">L’encyclopédie d’Arélia</span><h2>Chaque ville a une histoire. Chaque paysage, un monde à découvrir.</h2></div><a class="btn btn-gold" href="wiki/">Accéder au Wiki <span>↗</span></a></div></section>'''
layout('index.html','Portail impérial','Portail officiel fictif de l’Empire constitutionnel d’Arélia : carte, villes, territoires, institutions et encyclopédie.',home,'accueil')

# Empire
b='../';emp=head(b,[('L’Empire',None)],'Institutions','L’Empire constitutionnel','Un cadre politique à imaginer, un territoire à découvrir. Les décisions établies et les points encore ouverts sont distingués avec soin.')
emp+=f'''<section class="section"><div class="container content-grid"><div><span class="eyebrow dark">Présentation institutionnelle</span><h2>La Constitution au cœur de l’Empire.</h2><p class="body-copy">Arélia est un <strong>Empire constitutionnel</strong>. Sa capitale est Vésone, centre politique et symbolique du pays. La forme définitive des institutions, l’identité de la dynastie et les règles de gouvernement seront développées au fil de la construction de l’univers.</p><p class="body-copy">Pour conserver un monde cohérent, le portail distingue les données canoniques des propositions encore en cours d’écriture. Le Wiki pourra contenir plusieurs points de vue sur un même événement historique.</p><a href="{b}wiki/empire-constitutionnel/" class="btn btn-gold">Dossier constitutionnel ↗</a></div><div class="panel"><span class="eyebrow dark">Repères impériaux</span><h3>Fiche de l’État</h3><p><strong>Nom :</strong> Empire d’Arélia</p><p><strong>Capitale :</strong> Vésone</p><p><strong>Population :</strong> 100 millions d’habitants</p><p><strong>Superficie :</strong> 1 000 000 km²</p><p><strong>Dynastie :</strong> à définir</p><p><strong>Constitution :</strong> texte en construction</p><p class="fine-print">Le titre « portail impérial » s’inscrit dans la fiction. Aucune institution réelle.</p></div></div></section><section class="section section-cream"><div class="container"><div class="section-heading"><div><span class="eyebrow dark">À construire</span><h2>Les piliers de l’Empire</h2></div></div><div class="grid-three"><div class="panel"><span class="eyebrow dark">01</span><h3>La Couronne</h3><p>Rôle constitutionnel, succession, maison impériale et représentation de l’État.</p></div><div class="panel"><span class="eyebrow dark">02</span><h3>Les institutions</h3><p>Gouvernement, assemblées représentatives, justice et équilibre des pouvoirs.</p></div><div class="panel"><span class="eyebrow dark">03</span><h3>Les territoires</h3><p>Provinces, communes, métropoles et modalités d’autonomie locale.</p></div></div></div></section>'''
layout('empire/index.html','L’Empire','Découvrez le cadre constitutionnel et l’organisation politique fictive de l’Empire d’Arélia.',emp,'empire')

# Territoires
cities=['vesone','occidian','orientale','katoru','estrel'];regions=['massif-nord','lac-orelys','foret-arelia','desert-solmar','volcan-azran','littoral-est','yrmoth']
ter=head(b,[('Territoires',None)],'Géographie humaine et naturelle','Territoires & métropoles','D’une capitale parcourue de canaux aux villes de haute montagne, découvrez les paysages et les grands pôles urbains de l’île.')
ter+='<section class="section"><div class="container"><div class="section-heading"><div><span class="eyebrow dark">Les métropoles</span><h2>Cinq villes à explorer</h2></div><a class="text-link" href="../atlas/">Voir la carte ↗</a></div><div class="wiki-grid">'
for slug in cities:
 a=ARTICLE[slug];ter+=f'<a class="wiki-card" href="../wiki/{slug}/"><div class="meta"><span>Ville</span><span>↗</span></div><h3>{esc(a["title"])}</h3><p>{esc(a["summary"])}</p><span class="more">Consulter la fiche</span></a>'
ter+='</div></div></section><section class="section section-cream"><div class="container"><div class="section-heading"><div><span class="eyebrow dark">Milieux naturels</span><h2>La diversité du territoire</h2></div></div><div class="article-list">'
ter+=''.join(art_row('../',slug) for slug in regions)+'</div></div></section>'
layout('territoires/index.html','Territoires et villes','Les principales villes et régions naturelles de l’Empire d’Arélia.',ter,'territoires')

# Atlas
markers=[('katoru','Katoru',23,17),('eldan','',48,17),('orelis','Orélys',35,28),('occidian','Occidian',12,51),('estrel','Estrel',41,49),('vesone','Vésone',70,45),('orientale','Orientale',47,82),('solmar','Solmar',22,70),('azran','Azran',13,80),('forest','Forêt d’Arélia',69,68)]
markers=[('katoru','Katoru',25,18),('eldan','Eldan',49,16),('orelis','Orélys',37,29),('occidian','Occidian',15,53),('estrel','Estrel',43,49),('vesone','Vésone',72,45),('orientale','Orientale',46,80),('solmar','Solmar',21,70),('azran','Azran',15,81),('forest','Forêt',68,68)]
atlas=head('../',[('Atlas',None)],'Cartographie & exploration','Atlas interactif','Repérez les villes et les grands ensembles géographiques d’Arélia. Cliquez sur un point de la carte pour explorer sa fiche.')
atlas+='''<section class="section compact"><div class="container"><div class="atlas-shell" data-atlas data-base="../"><div class="atlas-topbar"><div><strong>Carte générale du territoire</strong><br><span>Relief illustratif · orientation nord en haut</span></div><div class="atlas-controls"><button type="button" aria-label="Agrandir" data-zoom-in>+</button><button type="button" aria-label="Réduire" data-zoom-out>−</button><button type="button" aria-label="Réinitialiser le cadrage" data-reset>↺</button></div></div><div class="atlas-workspace"><div class="atlas-viewport" aria-label="Carte illustrée d’Arélia avec points interactifs"><div class="atlas-transform"><img src="../assets/arelia-atlas.webp" alt="Carte satellite artistique du territoire d’Arélia" draggable="false"><div class="map-shade"></div><div class="map-canon"><span>Arélia · Données actuelles</span><strong>100 M hab. · 1 M km²</strong></div>'''
for id_,name,x,y in markers:
 atlas+=f'<button type="button" class="map-pin" style="left:{x}%;top:{y}%" data-place="{id_}" aria-label="Afficher {esc(name)}" aria-pressed="false"><span class="pin-dot"></span><span class="pin-title">{esc(name)}</span></button>'
atlas+='''</div></div><aside class="atlas-detail" data-map-details aria-live="polite"><h3>Explorer Arélia</h3><p>Sélectionnez un point sur la carte pour afficher ses informations.</p></aside></div><div class="map-legend"><span><b></b> Localités et lieux majeurs</span><span>Déplacez la carte · Zoom avec Ctrl + molette ou les boutons</span></div></div><p class="map-note">Carte de concept artistique non géoréférencée : distances et reliefs restent à normaliser avant un usage technique dans un moteur de jeu. Les chiffres canoniques sont 100 millions d’habitants et 1 000 000 km².</p></div></section><section class="section section-cream compact"><div class="container"><span class="eyebrow dark">Hydrographie</span><h2>Des montagnes jusqu’à l’océan</h2><p class="lead">Les eaux prennent leur source dans le massif du Nord, traversent la vallée centrale et atteignent leur embouchure à Occidian. Le lac d’Orélys, les canaux de Vésone et les bras d’eau de la forêt complètent le paysage.</p><a href="../wiki/reseau-hydrographique/" class="text-link">Lire le dossier hydrographique ↗</a></div></section>'''
layout('atlas/index.html','Atlas interactif','Carte interactive des villes, paysages et biomes de l’Empire d’Arélia.',atlas,'atlas')

# Journal
journal=head('../',[('Actualités',None)],'Gazette & projets','Chroniques d’Arélia','Journal éditorial fictif du projet. Les informations ci-dessous relatent la construction de cet univers et non des événements réels.')
journal+='''<section class="section compact"><div class="container"><div class="journal-entry"><span class="journal-date">Édition initiale · Dossier cartographique</span><h3>Une nouvelle géographie pour l’Empire</h3><p>La carte de référence associe un massif glaciaire septentrional, un grand fleuve central débouchant à Occidian, une capitale de canaux et le désert volcanique de Solmar.</p><a class="text-link" href="../atlas/">Consulter l’atlas ↗</a></div><div class="journal-entry"><span class="journal-date">Édition initiale · Institutions</span><h3>Le cadre constitutionnel d’Arélia</h3><p>Le régime retenu est celui d’un Empire constitutionnel. La rédaction de la Constitution, la définition de la Couronne et des pouvoirs représentatifs constituent les prochaines étapes de worldbuilding.</p><a class="text-link" href="../wiki/empire-constitutionnel/">Consulter le dossier ↗</a></div><div class="journal-entry"><span class="journal-date">Édition initiale · Encyclopédie</span><h3>Ouverture de l’encyclopédie</h3><p>Les premières notices sur la géographie, les villes et les institutions d’Arélia sont désormais reliées entre elles, avec une distinction entre éléments établis et sujets en conception.</p><a class="text-link" href="../wiki/">Explorer les articles ↗</a></div></div></section>'''
layout('journal/index.html','Chroniques d’Arélia','Chroniques du développement de l’univers fictif d’Arélia.',journal,'journal')

# Wiki index
wiki=head('../',[('Encyclopédie',None)],'Wiki d’Arélia','L’encyclopédie impériale','Explorez les lieux, les institutions et les paysages. Les articles distinguent les éléments déjà fixés et ceux qui restent à inventer.')
categories=['Tous','Empire','Villes','Géographie','Nature','Institutions','Histoire','Société']
wiki+='''<section class="section compact"><div class="container"><div class="section-heading"><div><span class="eyebrow dark">Explorer le savoir</span><h2>Répertoire des articles</h2></div><span class="fine-print" data-result-count>'''+str(len(ARTICLES))+''' articles</span></div><label for="wiki-search" class="screen-only">Rechercher dans l’encyclopédie</label><div class="search-wrap"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"></circle><path d="m16 16 5 5"></path></svg><input id="wiki-search" type="search" data-wiki-search placeholder="Rechercher une ville, un lieu, une institution…" autocomplete="off"></div><div class="filters" role="group" aria-label="Filtrer par catégorie">'''
for cat in categories: wiki+=f'<button type="button" class="filter'+(' active' if cat=='Tous' else '')+f'" aria-pressed="{str(cat=="Tous").lower()}" data-filter="{esc(cat)}">{esc(cat)}</button>'
wiki+='</div><div class="wiki-grid">'
for a in ARTICLES:
    terms=' '.join([a['title'],a['summary'],a['category']])
    wiki+=f'<a class="wiki-card" href="{a["slug"]}/" data-wiki-item data-category="{esc(a["category"],quote=True)}" data-search="{esc(terms,quote=True)}"><div class="meta"><span>{esc(a["category"])}</span><span>{esc(a["status"])}</span></div><h3>{esc(a["title"])}</h3><p>{esc(a["summary"])}</p><span class="more">Lire l’article ↗</span></a>'
wiki+='</div><p class="empty-results" data-search-empty hidden>Aucun article trouvé. Essayez une autre recherche ou sélectionnez « Tous ».</p></div></section><section class="section section-cream compact"><div class="container"><div class="notice"><strong>Principe éditorial.</strong> « Établi » signifie que le cadre de l’élément est retenu dans les cartes et décisions créatives. « En conception » identifie les points à inventer. Les détails d’un article peuvent évoluer au fil de la création de l’univers.</div></div></section>'
layout('wiki/index.html','Encyclopédie','Wiki encyclopédique de l’Empire fictif d’Arélia : villes, institutions, géographie, histoire et nature.',wiki,'wiki')

# Articles
for a in ARTICLES:
 b='../../';slug=a['slug']; status=a['status']; chain=[('Encyclopédie','wiki/'),(a['title'],None)]
 page=head(b,chain,a['category'],a['title'],a['summary'])
 page+='<section class="section compact"><div class="container article-layout"><article class="article-paper"><div class="article-meta"><span class="pill">'+esc(a['category'])+'</span><span class="pill">Statut : '+esc(status)+'</span></div><p class="article-intro">'+esc(a['intro'])+'</p><div class="keyfacts"><dl>'
 for key,val in a.get('facts',{}).items(): page+=f'<dt>{esc(key)}</dt><dd>{esc(val)}</dd>'
 page+='</dl></div>'
 for i,s in enumerate(a['sections']):
  page+=f'<h2 id="section-{i+1}">{esc(s[0])}</h2>'
  for p in s[1:]: page+='<p>'+esc(p)+'</p>'
 page+='<div class="notice"><strong>Note éditoriale :</strong> Cet article décrit un univers fictif en développement. Le statut et les informations pourront évoluer avec les prochaines versions de l’atlas.</div></article><aside class="aside-sticky"><div class="sidebar-panel"><h3>Dans cet article</h3>'
 for i,s in enumerate(a['sections']): page+=f'<a href="#section-{i+1}">{esc(s[0])}</a>'
 page+='</div><div class="sidebar-panel"><h3>Articles associés</h3>'
 for rel in a.get('related',[]):page+=f'<a href="{b}wiki/{rel}/">{esc(ARTICLE[rel]["title"])} ↗</a>'
 page+=f'</div><div class="sidebar-panel"><h3>Explorer davantage</h3><p>Retrouvez les autres dossiers et cartes de l’univers d’Arélia.</p><a href="{b}wiki/">Retour à l’encyclopédie ↗</a><a href="{b}atlas/">Ouvrir l’atlas ↗</a></div></aside></div></section>'
 layout(f'wiki/{slug}/index.html',a['title'],a['summary'],page,'wiki')

# Inventaire canonique exporté pour les intégrations futures (Unreal, wiki, etc.)
canon={'nation':'Empire d’Arélia','population':100000000,'superficie_km2':1000000,'regime':'Empire constitutionnel','capitale':'Vésone','articles':[{'slug':a['slug'],'title':a['title'],'category':a['category'],'status':a['status']} for a in ARTICLES]}
(SITE/'assets'/'referentiel.json').write_text(json.dumps(canon,ensure_ascii=False,indent=2),encoding='utf-8')
(SITE/'robots.txt').write_text('User-agent: *\nAllow: /\n',encoding='utf-8')
(SITE/'.nojekyll').touch()
print('Généré :',len(ARTICLES),'articles et 6 pages du portail')
